1. import { t } from "i18next";
2. import { navigate } from "raviger";
3. import { toast } from "sonner";
4. 
5. import * as Notifications from "@/Utils/Notifications";
6. import { HTTPError, StructuredError } from "@/Utils/request/types";
7. 
8. export function handleHttpError(error: Error) {
9.   // Skip handling silent errors and AbortError
10.   if (("silent" in error && error.silent) || error.name === "AbortError") {
11.     return;
12.   }
13. 
14.   if (!(error instanceof HTTPError)) {
15.     toast.error(error.message || t("something_went_wrong"));
16.     return;
17.   }
18. 
19.   const cause = error.cause;
20. 
21.   if (isNotFound(error)) {
22.     toast.error((cause?.detail as string) || t("not_found"));
23.     return;
24.   }
25. 
26.   if (contentTooLarge(error)) {
27.     toast.error(t("file_too_large"));
28.     return;
29.   }
30. 
31.   if (isSessionExpired(cause)) {
32.     handleSessionExpired();
33.     return;
34.   }
35. 
36.   if (isBadRequest(error)) {
37.     if (Array.isArray(cause)) {
38.       let handled = false;
39.       for (const obj of cause) {
40.         const errs = obj.errors;
41.         if (isPydanticError(errs)) {
42.           handled = true;
43.           handlePydanticErrors(errs);
44.           continue;
45.         }
46.       }
47.       if (handled) return;
48.     }
49. 
50.     const errs = cause?.errors;
51.     if (isPydanticError(errs)) {
52.       handlePydanticErrors(errs);
53.       return;
54.     }
55. 
56.     if (isStructuredError(cause)) {
57.       handleStructuredErrors(cause);
58.       return;
59.     }
60. 
61.     Notifications.BadRequest({ errs });
62.     return;
63.   }
64. 
65.   toast.error((cause?.detail as string) || t("something_went_wrong"));
66. }
67. 
68. function isSessionExpired(error: HTTPError["cause"]) {
69.   return (
70.     // If Authorization header is not valid
71.     error?.code === "token_not_valid" ||
72.     // If Authorization header is not provided
73.     error?.detail === "Authentication credentials were not provided."
74.   );
75. }
76. 
77. function handleSessionExpired() {
78.   if (!location.pathname.startsWith("/session-expired")) {
79.     navigate(`/session-expired?redirect=${window.location.href}`);
80.   }
81. }
82. 
83. function isBadRequest(error: HTTPError) {
84.   return error.status === 400 || error.status === 406;
85. }
86. 
87. function isNotFound(error: HTTPError) {
88.   return error.status === 404;
89. }
90. 
91. function contentTooLarge(error: HTTPError) {
92.   return error.status === 413;
93. }
94. 
95. type PydanticError = {
96.   type: string;
97.   loc?: string[];
98.   msg: string | Record<string, string>;
99.   input?: unknown;
100.   url?: string;
101. };
102. 
103. function isStructuredError(err: HTTPError["cause"]): err is StructuredError {
104.   return typeof err === "object" && !Array.isArray(err);
105. }
106. 
107. function handleStructuredErrors(cause: StructuredError) {
108.   for (const value of Object.values(cause)) {
109.     if (Array.isArray(value)) {
110.       value.forEach((err: any) => {
111.         if (typeof err === "string") {
112.           toast.error(err);
113.         } else if (err && typeof err === "object") {
114.           // Handle object errors - extract meaningful error messages
115.           const errorFields = ["detail", "msg", "error", "message"] as const;
116.           const errorMessage = errorFields.find(
117.             (field) => err[field] && typeof err[field] === "string",
118.           );
