420. interface SelectFromDefinitionCategoryPickerOptions {
421.   search?: string;
422.   navigateCategories?: string[];
423.   itemIndex?: number;
424. }
425. 
426. /**
427.  * Helper for ResourceDefinitionCategoryPicker component
428.  * This is different from selectFromCategoryPicker and handles definition selection
429.  * (used for activity definitions, etc.)
430.  *
431.  * @example
432.  * await selectFromDefinitionCategoryPicker(page, trigger, {
433.  *   navigateCategories: ["Lab Tests"],
434.  *   search: "Complete Blood Count",
435.  *   itemIndex: 0
436.  * });
437.  */
438. export async function selectFromDefinitionCategoryPicker(
439.   page: Page,
440.   trigger: Locator,
441.   {
442.     search,
443.     navigateCategories = [],
444.     itemIndex = 0,
445.   }: SelectFromDefinitionCategoryPickerOptions = {},
446. ) {
447.   await trigger.waitFor({ state: "visible" });
448.   await trigger.scrollIntoViewIfNeeded();
449. 
450.   // Close any existing popovers before opening
451.   await closeAnyOpenPopovers(page);
452. 
453.   await trigger.click();
454. 
455.   // Wait for the picker to open (could be dialog or popover)
456.   const dialog = page.getByRole("dialog").last();
457.   const hasDialog = await dialog.isVisible().catch(() => false);
458.   const popper = page.locator("[data-radix-popper-content-wrapper]").last();
459.   const scope = hasDialog ? dialog : popper;
460. 
461.   await scope.waitFor({ state: "visible" });
462. 
463.   // Navigate through categories if specified
464.   for (const categoryTitle of navigateCategories) {
465.     // Wait for the category to appear
466.     const categoryItem = scope.getByRole("option", {
467.       name: new RegExp(categoryTitle, "i"),
468.     });
469.     await categoryItem.waitFor({ state: "attached" });
470.     await categoryItem.waitFor({ state: "visible" });
471.     await categoryItem.click();
472. 
473.     // Wait for navigation to complete - wait for new options to load after category click
474.     const items = scope.getByRole("option");
475.     await items.first().waitFor({ state: "attached" });
476.   }
477. 
478.   // If search is provided, use search to filter items
479.   if (search) {
480.     const input = scope.locator('[data-slot="command-input"]').first();
481.     await input.waitFor({ state: "visible" });
482.     await input.fill("");
483.     await input.fill(search);
484. 
485.     // Wait for search results to load - options will be updated after input change
486.     const items = scope.getByRole("option");
487.     await items.first().waitFor({ state: "attached" });
488.   }
489. 
490.   // Wait for items to load
491.   const items = scope.getByRole("option");
492.   await items.first().waitFor({ state: "attached" });
493.   await items.first().waitFor({ state: "visible" });
494. 
495.   const count = await items.count();
496.   if (count === 0) {
497.     throw new Error("No items found in definition category picker");
498.   }
499. 
500.   // Select item at itemIndex
501.   const targetItem = items.nth(itemIndex);
502.   await targetItem.waitFor({ state: "attached" });
503.   await targetItem.waitFor({ state: "visible" });
504.   await targetItem.scrollIntoViewIfNeeded();
505.   await targetItem.click();
506. 
507.   // Wait for selection to register and dialog to close
508.   await scope.waitFor({ state: "hidden" }).catch(() => {});
509. }
510.

