    await locationDialog
      .getByRole("option", { name: DISPENSE_LOCATION })
      .first()
      .click();

    const sheet = getDispenseSheet(page);
    await expect(sheet).toBeVisible();
    return sheet;
  }

  async function addLineItem(page: Page, sheet: Locator, name: string) {
