      .getByRole("combobox")
      .filter({ hasText: "Add Item" })
      .first()
      .click();

    const picker = page.locator("[data-radix-popper-content-wrapper]").last();
    await picker.locator('[data-slot="command-input"]').fill(name);
    await picker.getByRole("option", { name }).first().click();
  }

